# Extract all songs with their titles and artists
all_songs = []

# Add songs from song library
for song in song_data:
    title = song['title']
    artists = [artist['name'] for artist in song['artists']]
    all_songs.append({
        'title': title,
        'artists': '|'.join(artists)
    })

# Add songs from album library (each album has song_ids)
for album in album_data:
    for song_id in album['song_ids']:
        # Find the song details using show_song API
        song_info = apis.spotify.show_song(song_id=song_id)
        if song_info:
            title = song_info['title']
            artists = [artist['name'] for artist in song_info['artists']]
            all_songs.append({
                'title': title,
                'artists': '|'.join(artists)
            })

# Add songs from playlist library (each playlist has song_ids)
for playlist in playlist_data:
    for song_id in playlist['song_ids']:
        # Find the song details using show_song API
        song_info = apis.spotify.show_song(song_id=song_id)
        if song_info:
            title = song_info['title']
            artists = [artist['name'] for artist in song_info['artists']]
            all_songs.append({
                'title': title,
                'artists': '|'.join(artists)
            })

# Remove duplicates while preserving order
unique_songs = []
seen_titles = set()

for song in all_songs:
    if song['title'] not in seen_titles:
        seen_titles.add(song['title'])
        unique_songs.append(song)

print(f"Found {len(unique_songs)} unique songs")
```

