all_song_ids = set()

# Get all songs from song library with pagination
print("Fetching songs from song library...")
song_library_page_index = 0
while True:
    song_page = apis.spotify.show_song_library(access_token=spotify_access_token, page_index=song_library_page_index)
    if not song_page:
        break
    for song in song_page:
        all_song_ids.add(song['song_id'])
    song_library_page_index += 1

# Get all albums from album library with pagination
print("Fetching albums from album library...")
album_library_page_index = 0
while True:
    album_page = apis.spotify.show_album_library(access_token=spotify_access_token, page_index=album_library_page_index)
    if not album_page:
        break
    for album in album_page:
        if 'song_ids' in album:
            all_song_ids.update(album['song_ids'])
        else:
            print(f"Album {album['album_id']} missing song_ids field")
    album_library_page_index += 1

# Get all playlists from playlist library with pagination
print("Fetching playlists from playlist library...")
playlist_library_page_index = 0
while True:
    playlist_page = apis.spotify.show_playlist_library(access_token=spotify_access_token, page_index=playlist_library_page_index)
