    file_path = file
    try:
        content_response = apis.file_system.show_file(file_path=file_path, access_token=file_system_access_token)
        content_str = content_response.get('content', '')
        file_contents[file_path] = content_str
    except Exception as e:
        file_contents[file_path] = f"Error: {str(e)}"

# Check if any content contains electricity-related information
electricity_bills = []
for file_path, content in file_contents.items():
    if ('electricity' in content.lower() or 
        'power' in content.lower() or 
        'electricity bill' in content.lower() or 
        'power bill' in content.lower()):
        electricity_bills.append(file_path)

# Extract cost from each electricity bill
total_cost = 0.0
for file_path, content in file_contents.items():
    if file_path in electricity_bills:
        # Extract cost from the content using regex
        cost_match = re.search(r'total|bill|charge|cost|amount\s*[:\-]\s*([0-9]+(?:\.[0-9]+)?(?:,\d+)?(?:[deD]|$))', content, re.IGNORECASE)
        if cost_match:
            cost_str = cost_match.group(1).replace(',', '').strip()
            try:
                cost = float(cost_str)
                total_cost += cost
            except ValueError:
                # If cost can't be parsed, try to extract from other patterns
                cost_match2 = re.search(r'([0-9]+(?:\.[0-9]+)?(?:,\d+)?(?:[deD]|$))', content, re.IGNORECASE)
                if cost_match2:
                    cost_str2 = cost_match2.group(1).replace(',', '').strip()
                    try:
                        cost = float(cost_str2)
                        total_cost += cost
                    except ValueError:
                        continue
        else:
            # If no cost found, try to extract from other patterns
            cost_match2 = re.search(r'([0-9]+(?:\.[0-9]+)?(?:,\d+)?(?:[deD]|$))', content, re.IGNORECASE)
            if cost_match2:
                cost_str2 = cost_match2.group(1).replace(',', '').strip()
                try:
                    cost = float(cost_str2)
                    total_cost += cost
                except ValueError:
                    continue

print(f"Total cost of electricity bills: ${total_cost:.2f}")
