# Process each file in the cable directory
for file_path in bills_files:
    # Check if this is a file in the cable directory (has an extension)
    if 'cable/' in file_path and file_path.endswith(('.txt', '.pdf')):
        # Extract the file name from the path
        file_name = file_path.split('/')[-1]

        # Retrieve the content of the file
        try:
            file_content_response = apis.file_system.show_file(file_path=file_path, access_token=file_system_access_token)

            # Extract content string - it might be in the content key or directly in the response
            content_str = file_content_response.get('content', '')

            # Check if we have content to work with
            if not content_str or content_str.strip() == '':
                print(f"Empty or no content for file: {file_name}")
                continue

            # Check if the content contains cable-related information
            if 'cable' in content_str.lower():
                # Extract the cost from the content (assuming it's in a format like "Total: $123.45" or "Total Amount => $123.45")
                cost_match = re.search(r'total|bill|charge|cost|amount\s*[:\-]\s*([0-9]+(?:\.[0-9]+)?(?:,\d+)?(?:[deD]|$))', content_str, re.IGNORECASE)
                if cost_match:
                    cost_str = cost_match.group(1).replace(',', '').strip()
                    try:
                        cost = float(cost_str)
                        total_cost += cost
                    except ValueError:
                        # Try alternative pattern if first fails
                        cost_match2 = re.search(r'([0-9]+(?:\.[0-9]+)?(?:,\d+)?(?:[deD]|$))', content_str, re.IGNORECASE)
                        if cost_match2:
                            cost_str2 = cost_match2.group(1).replace(',', '').strip()
                            try:
                                cost = float(cost_str2)
                                total_cost += cost
                            except ValueError:
                                continue
                else:
                    # Fallback: try to extract any number in content
                    cost_match3 = re.search(r'([0-9]+(?:\.[0-9]+)?(?:,\d+)?(?:[deD]|$))', content_str, re.IGNORECASE)
                    if cost_match3:
                        cost_str3 = cost_match3.group(1).replace(',', '').strip()
                        try:
                            cost = float(cost_str3)
                            total_cost += cost
                        except ValueError:
                            continue
        except Exception as e:
            print(f"Error reading file {file_name}: {str(e)}")

print(f"Total cost of cable bills: ${total_cost:.2f}")
