        if 'like_count' in song_info:
            song_details[song_id] = song_info
        else:
            print(f"Warning: Song {song_id} missing like_count field - this is unexpected")
    except Exception as e:
        print(f"Error fetching song {song_id}: {e}")
        continue

print(f"Retrieved details for {len(song_details)} songs")
